sealed interface SyncResult {
    data class Synced(val records: Int) : SyncResult
    data class Conflicted(val ids: List<String>) : SyncResult
    data class Failed(val cause: Throwable, val retryable: Boolean) : SyncResult
}

class SyncEngine(private val api: Api, private val db: Db) {

    suspend fun sync(pending: List<Mutation>): SyncResult = withContext(Dispatchers.IO) {
        val lock = db.acquireSyncLock()
        try {
            var applied = 0
            val conflicts = mutableListOf<String>()

            for (mutation in pending) {
                // Cancellation is cooperative. A loop that never suspends
                // never notices it was cancelled, so it has to ask.
                ensureActive()

                when (val outcome = api.apply(mutation)) {
                    is Applied -> { db.commit(outcome.record); applied++ }
                    is Conflict -> conflicts += outcome.id
                }
            }

            if (conflicts.isEmpty()) SyncResult.Synced(applied)
            else SyncResult.Conflicted(conflicts)
        } catch (e: IOException) {
            SyncResult.Failed(e, retryable = true)
        } finally {
            // Without NonCancellable this cleanup is itself cancelled when the
            // scope dies, and the lock is never released.
            withContext(NonCancellable) { db.releaseSyncLock(lock) }
        }
    }
}

// At the call site an exhaustive when is required: add a fourth result and
// this stops compiling, which is the entire point of the sealed interface.
when (val result = engine.sync(pending)) {
    is SyncResult.Synced -> showToast("${result.records} synced")
    is SyncResult.Conflicted -> openConflictScreen(result.ids)
    is SyncResult.Failed -> if (result.retryable) scheduleRetry() else report(result.cause)
}
